def divide_safe(a, b):
    try:
        result = a / b
        return f"{a} / {b} = {result}"
    except ZeroDivisionError:
        return "Error: Cannot divide by zero"
    except TypeError:
        return "Error: Invalid type"
    finally:
        print("Division attempted")

print(divide_safe(10, 2))
print(divide_safe(10, 0))
print(divide_safe(10, "a"))

